MAP
    NAME "SS_MAP_GRAL_LIMITE_MUNICIPAL"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_limite_municipal.log"
    DEBUG 0
    LAYER 
        NAME "SS_MAP_LIMITE_MUNICIPAL"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        METADATA 
            'ows_title' 'SS_MAP_GRAL_LIMITE_MUNICIPAL'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
            "styles" "defult"
            'wms_getfeatureinfo_formatlist' 'geojson'
        END #METADATA
        LABELMAXSCALE 20000
            INCLUDE 'includes/conexion.map'
        TYPE LINE
        DATA "geometry from limite_municipal using unique gid using srid=32614"
        CLASS
            NAME "Limite Municipal"
            STYLE
                WIDTH 4
                COLOR 139 99 55
                OUTLINECOLOR 0 0 0
            END #STYLE
        END #CLASS 
    END #LAYER
    LAYER
        NAME "SS_MAP_NOMBRE_MUNICIPIOS"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE POINT
        DATA "geometry from (select gid,geometry,(nombre_mun || area_km2 || ' Km²') as txt from nombre_municipios) as tmp using unique gid using srid=32614"
        LABELITEM "txt"
        LABELCACHE OFF
        CLASS
            NAME "Nombre de Municipios"
            LABEL
                TYPE TRUETYPE
                OFFSET 0 22
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                FONT "arial"
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP